import type * as Phaser from "phaser";
import { getSettings } from "./Save";

/** Sound effects in public/audio/ (generated by `npm run sfx`). */
export const SfxKey = {
  JUMP: "jump",
  LAND: "land",
  COIN: "coin",
  HURT: "hurt",
  DEATH: "death",
  CHECKPOINT: "checkpoint",
  LEVEL_COMPLETE: "levelComplete",
  MENU_SELECT: "menuSelect",
  STOMP: "stomp",
  SWORD_SWING: "swordSwing",
  ENEMY_HIT: "enemyHit",
} as const;

export type SfxKeyValue = (typeof SfxKey)[keyof typeof SfxKey];

export function loadSfx(scene: Phaser.Scene): void {
  for (const key of Object.values(SfxKey)) {
    scene.load.audio(key, `/audio/${key}.wav`);
  }
}

/**
 * Play a sound effect on the SFX channel (§2.4: separate SFX and music
 * volumes plus a global mute, all from the saved settings). Silently skips
 * missing sounds.
 */
export function playSfx(scene: Phaser.Scene, key: SfxKeyValue): void {
  const { muted, sfxVolume } = getSettings();
  if (muted || sfxVolume <= 0) return;
  if (!scene.cache.audio.exists(key)) return;
  scene.sound.play(key, { volume: sfxVolume });
}
